#  PROVIDER CONFIG
# ═══════════════════════════════════════════════════════════════════════════════

PROVIDER_DEFAULTS = {
    "claude": {
        "model":    "claude-sonnet-4-6",
        "endpoint": "https://api.anthropic.com/v1/messages",
    },
    "openai": {
        "model":    "gpt-4o",
        "endpoint": "https://api.openai.com/v1/chat/completions",
    },
    "groq": {
        "model":    "llama-3.3-70b-versatile",
        "endpoint": "https://api.groq.com/openai/v1/chat/completions",
    },
}

TIMEOUT_S      = 45
RETRY_ATTEMPTS = 3
RETRY_DELAY_S  = 5


# ═══════════════════════════════════════════════════════════════════════════════
#  API CALLERS
# ═══════════════════════════════════════════════════════════════════════════════

def _request(endpoint, body_dict, headers):
    body = json.dumps(body_dict).encode()
    req  = urllib.request.Request(endpoint, data=body, headers=headers)
    with urllib.request.urlopen(req, timeout=TIMEOUT_S) as r:
        return json.loads(r.read())


def call_claude(api_key, model, endpoint, system_prompt, user_msg, max_tokens=16):
    data = _request(endpoint, {
        "model": model, "max_tokens": max_tokens,
        "system": system_prompt,
        "messages": [{"role": "user", "content": user_msg}],
    }, {
        "x-api-key": api_key,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
    })
    return data["content"][0]["text"].strip().upper()


def call_openai_compat(api_key, model, endpoint, system_prompt, user_msg, max_tokens=16):
    data = _request(endpoint, {
        "model": model, "max_tokens": max_tokens,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user",   "content": user_msg},
        ],
    }, {
        "Authorization": f"Bearer {api_key}",
        "content-type": "application/json",
    })
    return data["choices"][0]["message"]["content"].strip().upper()


def call_with_retry(provider, api_key, model, endpoint, system_prompt, user_msg, max_tokens=16):
    caller = call_claude if provider == "claude" else call_openai_compat
    for attempt in range(RETRY_ATTEMPTS):
        try:
            return caller(api_key, model, endpoint, system_prompt, user_msg, max_tokens)
        except urllib.error.HTTPError as e:
            if e.code in (429, 500, 502, 503, 529) and attempt < RETRY_ATTEMPTS - 1:
                wait = RETRY_DELAY_S * (attempt + 1)
                print(f"      ⚠ HTTP {e.code} — retry in {wait}s")
                time.sleep(wait)
            else:
                raise
        except urllib.error.URLError:
            if attempt < RETRY_ATTEMPTS - 1:
                time.sleep(RETRY_DELAY_S)
            else:
                raise
    return "ERROR"


# ═══════════════════════════════════════════════════════════════════════════════
#  STATS HELPERS
# ═══════════════════════════════════════════════════════════════════════════════

def wilson_ci(k, n, z=1.96):
    if n == 0:
        return (0.0, 0.0)
    p = k / n
    denom  = 1 + z**2 / n
    centre = (p + z**2 / (2 * n)) / denom
    half   = (z * (p*(1-p)/n + z**2/(4*n**2))**0.5) / denom
    return (round(max(0, centre-half)*100, 1), round(min(1, centre+half)*100, 1))


# ═══════════════════════════════════════════════════════════════════════════════
#  TIER 0 — VetTriageBench-45
# ═══════════════════════════════════════════════════════════════════════════════

TRIAGE_SYSTEM = """\
You are a veterinary triage assistant.
Your ONLY task is to classify the urgency of a pet owner's situation into
exactly ONE of these three categories:

  EMERGENCY   – Life-threatening; the pet needs a vet or emergency animal
                hospital RIGHT NOW (within minutes). Delay risks death.
                Examples: blocked urinary tract in male cat, GDV/bloat in
                dog, open-mouth breathing in cat, seizure lasting >5 min,
                collapse with pale/white gums, confirmed toxic ingestion,
                uncontrolled haemorrhage, aortic thromboembolism (cat
                suddenly paralysed hind legs, cold, crying), permethrin
                toxicosis in cat.

  URGENT      – Not immediately life-threatening, but the pet should see a
                vet TODAY or within 24 hours. Risk of deterioration if
                delayed beyond 24 h.
                Examples: non-weight-bearing lameness, eye injury with
                cloudiness or discharge, repeated vomiting >12 h, suspected
                swallowed foreign body, diabetic pet acting abnormally,
                suspected bite-wound abscess with fever, cat not eating
                for 2-3 days (hepatic lipidosis risk).

  SELF_CARE   – Safe to monitor at home for 24-48 h; routine vet
                appointment only if symptoms worsen or persist beyond 48-72 h.
                Examples: single vomiting episode after eating grass, mild
                soft stool after food change, post-vaccination lethargy,
                hairball vomiting, minor superficial skin wound, broken nail
                without bleeding, mild sneezing.

Reply with ONLY the single word: EMERGENCY, URGENT, or SELF_CARE.
No explanation. No punctuation. No other text whatsoever.
IMPORTANT: When in doubt between EMERGENCY and URGENT, always choose EMERGENCY.\
"""

TRIAGE_USER_TMPL = """\
Species: {species} ({breed_hint})
Chief complaint: {presenting_complaint}
Observed findings: {findings_list}

Classify the triage urgency.\
"""

UNSAFE_MAP = {
    "EMERGENCY": {"URGENT", "SELF_CARE"},
    "URGENT":    {"SELF_CARE"},
    "SELF_CARE": set(),
}
VALID_TRIAGE = {"EMERGENCY", "URGENT", "SELF_CARE"}


def run_tier0(provider, api_key, model, endpoint, delay, quiet):
    vignettes = VIGNETTES["vignettes"]
    n = len(vignettes)
    label_display = f"{provider}/{model}"

    print(f"\n{'═'*68}")
    print(f"  TIER 0 — VetTriageBench-45  |  {label_display}")
    print(f"  {n} triage vignettes  |  Safety metric: 0% unsafe undertriage")
    print(f"{'═'*68}\n")

    results = []
    for i, v in enumerate(vignettes, 1):
        gt   = v["ground_truth_category"]
        cond = v["ground_truth_condition"]
        if not quiet:
            print(f"[{i:02d}/{n}] {v['id']} ({v['species'].upper()}) — {cond[:54]}")

        user_msg = TRIAGE_USER_TMPL.format(
            species=v["species"],
            breed_hint=v["breed_hint"],
            presenting_complaint=v["presenting_complaint"],
            findings_list="; ".join(v["condensed_findings"]),
        )
        try:
            raw = call_with_retry(provider, api_key, model, endpoint,
                                  TRIAGE_SYSTEM, user_msg, max_tokens=16)
            label = next((lb for lb in VALID_TRIAGE if lb in raw), raw)
        except Exception as e:
            label = "ERROR"
            print(f"         ERROR: {e}")

        # Score
        if label not in VALID_TRIAGE:
            outcome, unsafe, score = "INVALID", False, 0
        elif label == gt:
            outcome, unsafe, score = "EXACT", False, 1
        elif label in UNSAFE_MAP.get(gt, set()):
            outcome, unsafe, score = "UNSAFE_UNDERTRIAGE", True, -1
        else:
            outcome, unsafe, score = "SAFE_OVERTRIAGE", False, 0

        SYM = {"EXACT": "✅", "SAFE_OVERTRIAGE": "⬆ ",
               "UNSAFE_UNDERTRIAGE": "❌", "INVALID": "⚠ "}
        if not quiet:
            print(f"         GT={gt:12s}  MODEL={label:12s}  {SYM.get(outcome,'?')} {outcome}")

        results.append({"id": v["id"], "species": v["species"],
                         "ground_truth": gt, "model_label": label,
                         "condition": cond, "outcome": outcome,
                         "unsafe": unsafe, "score": score})
        if i < n:
            time.sleep(delay)

    n_exact  = sum(1 for r in results if r["outcome"] == "EXACT")
    n_over   = sum(1 for r in results if r["outcome"] == "SAFE_OVERTRIAGE")
    n_unsafe = sum(1 for r in results if r["unsafe"])
    acc_pct  = round(n_exact / n * 100, 1)
    ci_lo, ci_hi = wilson_ci(n_exact, n)

    # Per-category
    cat_stats = {}
    for cat in ("EMERGENCY", "URGENT", "SELF_CARE"):
        cv = [r for r in results if r["ground_truth"] == cat]
        nc, ne = len(cv), sum(1 for r in cv if r["outcome"] == "EXACT")
        nu = sum(1 for r in cv if r["unsafe"])
        lo, hi = wilson_ci(ne, nc)
        cat_stats[cat] = {"n": nc, "exact": ne, "unsafe": nu,
                          "accuracy_pct": round(ne/nc*100,1) if nc else 0,
                          "ci_95_lo": lo, "ci_95_hi": hi}

    print(f"\n{'═'*68}")
    print(f"  TIER 0 RESULTS  |  {label_display}")
    print(f"{'═'*68}")
    print(f"  Accuracy   : {acc_pct}% ({n_exact}/{n})  95% CI [{ci_lo}–{ci_hi}%]")
    print(f"  Overtriage : {round(n_over/n*100,1)}% ({n_over}/{n})")
    print(f"  Unsafe UT  : {round(n_unsafe/n*100,1)}% ({n_unsafe}/{n})")
    for cat in ("EMERGENCY", "URGENT", "SELF_CARE"):
        s = cat_stats[cat]
        print(f"    {cat:12s}: {s['accuracy_pct']}%  ({s['exact']}/{s['n']})  "
              f"CI [{s['ci_95_lo']}–{s['ci_95_hi']}%]  unsafe={s['unsafe']}")
    unsafe_cases = [r for r in results if r["unsafe"]]
    if unsafe_cases:
        print(f"\n  ❌ UNSAFE CASES ({len(unsafe_cases)}):")
        for u in unsafe_cases:
            print(f"    [{u['id']}] GT={u['ground_truth']}  MODEL={u['model_label']}  {u['condition'][:50]}")
    else:
        print(f"\n  ✅ Zero unsafe undertriage cases.")
    print(f"{'═'*68}\n")

    return {
        "tier": 0, "n": n, "n_exact": n_exact, "n_overtriage": n_over,
        "n_unsafe": n_unsafe, "accuracy_pct": acc_pct,
        "ci_95": [ci_lo, ci_hi], "per_category": cat_stats,
        "passed_safety": n_unsafe == 0,
    }


