MCQ_SYSTEM_T1 = """\
You are taking a veterinary licensing examination.
Each question is a multiple-choice question with options A through E.
You must select the single best answer.

Reply with ONLY the single letter: A, B, C, D, or E.
No explanation. No punctuation. No other text whatsoever.\
"""

MCQ_SYSTEM_T2 = """\
You are taking a veterinary clinical licensing examination (NAVLE level).
Each question is a multiple-choice question with options A through E.
You must select the single best answer.

Reply with ONLY the single letter: A, B, C, D, or E.
No explanation. No punctuation. No other text whatsoever.\
"""

MCQ_USER_TMPL = """\
{question}

{options_text}

Answer:\
"""

VALID_MCQ = {"A", "B", "C", "D", "E"}


def extract_mcq_answer(raw):
    raw = raw.strip().upper()
    if raw in VALID_MCQ:
        return raw
    for ch in raw:
        if ch in VALID_MCQ:
            return ch
    return "INVALID"


def run_mcq_tier(tier_num, provider, api_key, model, endpoint, delay, quiet):
    dataset   = TIER1 if tier_num == 1 else TIER2
    questions = dataset["questions"]
    threshold = dataset["passing_threshold_pct"]
    system_prompt = MCQ_SYSTEM_T1 if tier_num == 1 else MCQ_SYSTEM_T2
    n = len(questions)
    label_display = f"{provider}/{model}"

    tier_labels = {
        1: f"TIER 1 — VetExamBench-60 (ICVA VEA Basic Sciences)",
        2: f"TIER 2 — VetLicenseBench-60 (NAVLE/CAPC Clinical)",
    }

    print(f"\n{'═'*68}")
    print(f"  {tier_labels[tier_num]}  |  {label_display}")
    print(f"  {n} questions  |  Passing: >={threshold}%")
    print(f"{'═'*68}\n")

    results = []
    for i, q in enumerate(questions, 1):
        options_text = "\n".join(f"({k}) {v}" for k, v in q["options"].items())
        user_msg = MCQ_USER_TMPL.format(
            question=q["question"],
            options_text=options_text,
        )
        try:
            raw    = call_with_retry(provider, api_key, model, endpoint,
                                     system_prompt, user_msg, max_tokens=4)
            answer = extract_mcq_answer(raw)
        except Exception as e:
            answer = "INVALID"
            print(f"  [{q['id']}] ERROR: {e}")

        correct    = q["correct_answer"]
        is_correct = (answer == correct)

        if not quiet:
            mark = "✅" if is_correct else ("❌" if answer != "INVALID" else "⚠️")
            print(f"  [{q['id']}] {mark}  GT={correct}  MODEL={answer}  "
                  f"({q['category']})  {q['question'][:50]}...")

        results.append({
            "id": q["id"], "category": q["category"],
            "correct_answer": correct, "model_answer": answer,
            "is_correct": is_correct,
        })
        if i < n:
            time.sleep(delay)

    n_correct = sum(1 for r in results if r["is_correct"])
    n_invalid = sum(1 for r in results if r["model_answer"] == "INVALID")
    acc_pct   = round(n_correct / n * 100, 1)
    passed    = acc_pct >= threshold
    ci_lo, ci_hi = wilson_ci(n_correct, n)

    # Per-category
    categories = sorted(set(r["category"] for r in results))
    cat_stats  = {}
    for cat in categories:
        cv = [r for r in results if r["category"] == cat]
        nc, ne = len(cv), sum(1 for r in cv if r["is_correct"])
        lo, hi = wilson_ci(ne, nc)
        cat_stats[cat] = {"n": nc, "correct": ne,
                          "accuracy_pct": round(ne/nc*100,1) if nc else 0,
                          "ci_95_lo": lo, "ci_95_hi": hi}

    icon = "✅ PASSED" if passed else "❌ FAILED"
    print(f"\n{'═'*68}")
    print(f"  TIER {tier_num} RESULTS  |  {label_display}")
    print(f"{'═'*68}")
    print(f"  Score : {n_correct}/{n}  ({acc_pct}%)  95% CI [{ci_lo}–{ci_hi}%]")
    print(f"  Pass  : >={threshold}%  →  {icon}")
    if n_invalid:
        print(f"  Invalid responses: {n_invalid}")
    for cat in categories:
        s = cat_stats[cat]
        print(f"    {cat:26s}: {s['accuracy_pct']:5.1f}%  ({s['correct']}/{s['n']})  "
              f"CI [{s['ci_95_lo']}–{s['ci_95_hi']}%]")
    print(f"{'═'*68}\n")

    return {
        "tier": tier_num, "n": n, "n_correct": n_correct, "n_invalid": n_invalid,
        "accuracy_pct": acc_pct, "ci_95": [ci_lo, ci_hi],
        "passed": passed, "pass_threshold_pct": threshold,
        "per_category": cat_stats,
    }


# ═══════════════════════════════════════════════════════════════════════════════
#  COMBINED VERDICT
# ═══════════════════════════════════════════════════════════════════════════════

def print_combined_verdict(summaries, provider, model):
    print(f"\n{'#'*68}")
    print(f"  🏛  FULL SUITE VERDICT — PetAiNurse Benchmark")
    print(f"  Model: {provider} / {model}")
    print(f"{'#'*68}")

    checks = {
        "Triage Safety (0% unsafe UT)": summaries.get(0, {}).get("passed_safety"),
        "VEA Basic Sciences (>=70%)":   summaries.get(1, {}).get("passed"),
        "Clinical Licensing (>=60%)":   summaries.get(2, {}).get("passed"),
    }

    if 0 in summaries:
        s = summaries[0]
        icon = "✅" if s["passed_safety"] else "❌"
        print(f"\n  {icon} Tier 0 — VetTriageBench-45")
        print(f"     Accuracy: {s['accuracy_pct']}%  95% CI [{s['ci_95'][0]}–{s['ci_95'][1]}%]")
        print(f"     Unsafe undertriage: {s['n_unsafe']}/{s['n']}  ({'SAFE ✅' if s['passed_safety'] else 'UNSAFE ❌'})")

    for t in (1, 2):
        if t in summaries:
            s = summaries[t]
            icon = "✅" if s["passed"] else "❌"
            labels = {1: "VetExamBench-60  (ICVA VEA)", 2: "VetLicenseBench-60 (NAVLE/CAPC)"}
            print(f"\n  {icon} Tier {t} — {labels[t]}")
            print(f"     Score: {s['n_correct']}/{s['n']}  ({s['accuracy_pct']}%)  "
                  f"95% CI [{s['ci_95'][0]}–{s['ci_95'][1]}%]")
            print(f"     Threshold: >={s['pass_threshold_pct']}%  →  {'PASSED' if s['passed'] else 'FAILED'}")

    all_passed = all(v for v in checks.values() if v is not None)
    print(f"\n{'─'*68}")
    if all_passed:
        print(f"  🎓 OVERALL VERDICT: PASSED ALL BENCHMARKS")
        print()
        print(f"  \"{provider} / {model}\" demonstrates:")
        print(f"    • Safe veterinary triage (0% unsafe undertriage)")
        print(f"    • Basic science knowledge at veterinary degree level")
        print(f"    • Clinical licensing knowledge at NAVLE level")
        print()
        print(f"  Marketing claim: \"Our AI would pass vet school — and is")
        print(f"  safer than the average student.\"")
    else:
        failed = [k for k, v in checks.items() if v is False]
        print(f"  📚 OVERALL VERDICT: DID NOT PASS ALL BENCHMARKS")
        print(f"  Failed: {', '.join(failed)}")
    print(f"{'#'*68}\n")


# ═══════════════════════════════════════════════════════════════════════════════
#  SAVE RESULTS
# ═══════════════════════════════════════════════════════════════════════════════

def save_results(summaries, provider, model, output_path):
    doc = {
        "suite": "PetAiNurse Full Benchmark Suite",
        "provider": provider, "model": model,
        "run_date": datetime.now().isoformat(),
        "tiers": {str(k): v for k, v in summaries.items()},
    }
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(doc, f, indent=2, ensure_ascii=False)
    print(f"  Results saved → {output_path}")


# ═══════════════════════════════════════════════════════════════════════════════
#  CLI
# ═══════════════════════════════════════════════════════════════════════════════

def main():
    p = argparse.ArgumentParser(
        description="PetAiNurse / KiraAIpet — Full Benchmark Suite",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    p.add_argument("--provider", "-p", choices=["claude", "openai", "groq"],
                   required=True)
    p.add_argument("--model",    "-m", default=None)
    p.add_argument("--api-key",  "-k", default=None)
    p.add_argument("--tier",     "-t", type=int, choices=[0, 1, 2], default=None,
                   help="Run only this tier (default: all)")
    p.add_argument("--delay",    "-d", type=float, default=1.2,
                   help="Seconds between API calls (default: 1.2)")
    p.add_argument("--quiet",    action="store_true")
    p.add_argument("--output",   "-o", default=None)
    args = p.parse_args()

    provider = args.provider
    model    = args.model or PROVIDER_DEFAULTS[provider]["model"]
    endpoint = PROVIDER_DEFAULTS[provider]["endpoint"]
    api_key  = args.api_key

    if not api_key:
        env_map = {
            "claude": ["ANTHROPIC_API_KEY", "Claude_API_Key"],
            "openai": ["OPENAI_API_KEY"],
            "groq":   ["GROQ_API_KEY"],
        }
        for env in env_map[provider]:
            api_key = os.environ.get(env, "")
            if api_key:
                break

    if not api_key:
        print(f"ERROR: No API key for {provider}.")
        sys.exit(1)

    tiers_to_run = [args.tier] if args.tier is not None else [0, 1, 2]
    summaries    = {}

    for tier in tiers_to_run:
        if tier == 0:
            summaries[0] = run_tier0(provider, api_key, model, endpoint,
                                     args.delay, args.quiet)
        elif tier == 1:
            summaries[1] = run_mcq_tier(1, provider, api_key, model, endpoint,
                                        args.delay, args.quiet)
        elif tier == 2:
            summaries[2] = run_mcq_tier(2, provider, api_key, model, endpoint,
                                        args.delay, args.quiet)

    if len(summaries) > 1:
        print_combined_verdict(summaries, provider, model)

    safe_model = model.replace("/", "_").replace("-", "_")
    datestamp  = datetime.now().strftime("%Y%m%d_%H%M")
    output = args.output or f"benchmark_results_{provider}_{safe_model}_{datestamp}.json"
    save_results(summaries, provider, model, output)


if __name__ == "__main__":
    main()
